using System.ComponentModel.Composition;
[ExportAttribute(identifierStr(Dynamics.AX.Application.TAMRebateQueryBuilder))]
[ExportMetadata(enumStr(ModuleInventCustVend), enumLiteralStr(ModuleInventCustVend, Cust))]
[ExportMetadata(enumStr(TAMRebateSourceType), enumLiteralStr(TAMRebateSourceType, METExternalSalesData))]
public final class METTAMRebateQueryBuilderCustExternalData extends TAMRebateQueryBuilder
{
}

Method.Source:
public FieldId orderAccountJourTableFieldId()
{
    return fieldNum(METRebateScanSupplierTable, CustAccount);
}

public FieldId invoiceAccountJourTableFieldId()
{
    return fieldNum(METRebateScanSupplierTable, CustAccount);
}

protected FieldId accountMainTableFieldId()
{
    return fieldNum(CustTable, AccountNum);
}

public FieldId dateFieldId()
{
    return fieldNum(METRebateScanSupplierTable, TransactionDate);
}

protected FieldId inventTransIdFieldId()
{
    return fieldNum(METRebateScanSupplierTable, TransactionNumber);
}

public FieldId itemFieldId()
{
    return fieldNum(METRebateScanSupplierTable, ItemId);
}

public FieldId inventDimIdFieldId()
{
    // TODO Find a way to return a field to simulate inventDimBlank
    return fieldNum(SalesLine, InventDimId);
}

public TableId journalTable()
{
    // TODO we don't really have a header table with METRebateScanSupplierTable
    return tableNum(METRebateScanSupplierTable);
}

public FieldId transTableRecIdFieldId()
{
    return fieldNum(METRebateScanSupplierTable, RecId);
}

protected void addTransRange()
{
    /*query.dataSourceTable(tableNum(SalesLine)).addRange(fieldNum(SalesLine, LineDeliveryType)).value(SysQuery::valueNot(LineDeliveryType::OrderLineWithMultipleDeliveries));
    this.hideReturnReservationLine();*/

    // only select records with a customer account
    query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, CustAccount)).value(SysQuery::valueNotEmptyString());
    query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, VendAccount)).value(SysQuery::valueEmptyString());
}

