protected void addOrderTypeRange()
{
    if (TAMRebateParameters::find().IncludeOrderTypeJournal == NoYes::No)
    {
        SysQuery::findOrCreateRange(query.dataSourceTable(tableNum(SalesTable)), fieldNum(SalesTable, SalesType)).value(SysQuery::valueNot(SalesType::Journal));
